#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>

sem_t mutex;
int counter = 0;

void* threadFunc(void* arg) {
    sem_wait(&mutex); // Entry section: wait(S)
    // Critical Section
    counter++;
    printf("Thread %ld in CS, counter = %d\n", (long)arg, counter);
    sem_post(&mutex); // Exit section: signal(S)
    return NULL;
}

int main() {
    pthread_t t1, t2;
    sem_init(&mutex, 0, 1); // Binary semaphore initialized to 1
    pthread_create(&t1, NULL, threadFunc, (void*)1);
    pthread_create(&t2, NULL, threadFunc, (void*)2);
    pthread_join(t1, NULL); pthread_join(t2, NULL);
    sem_destroy(&mutex);
    return 0;
}

