#include <stdio.h>

int main() {
    int n = 3, m = 3; // 3 processes, 3 resource types
    int alloc[3][3] = {{0, 1, 0}, {2, 0, 0}, {3, 0, 2}};
    int max[3][3] = {{7, 5, 3}, {3, 2, 2}, {9, 0, 2}};
    int avail[3] = {3, 3, 2};
    int need[3][3];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) need[i][j] = max[i][j] - alloc[i][j];
    }
    int finish[3] = {0}, safeSeq[3], count = 0;
    while (count < n) {
        int found = 0;
        for (int p = 0; p < n; p++) {
            if (!finish[p]) {
                int j;
                for (j = 0; j < m; j++) if (need[p][j] > avail[j]) break;
                if (j == m) {
                    for (int k = 0; k < m; k++) avail[k] += alloc[p][k];
                    safeSeq[count++] = p;
                    finish[p] = 1;
                    found = 1;
                }
            }
        }
        if (!found) { printf("System is in UNSAFE STATE!\n"); return 1; }
    }
    printf("Safe Sequence exists: ");
    for (int i = 0; i < n; i++) printf("P%d ", safeSeq[i]);
    printf("\n");
    return 0;
}

