#include <stdio.h>
#include <stdlib.h>

int main() {
    int req[] = {98, 183, 37, 122, 14, 124, 65, 67};
    int n = 8, head = 53, totalMovement = 0;
    int done[8] = {0};

    for (int i = 0; i < n; i++) {
        int minDiff = 9999, chosen = -1;
        for (int j = 0; j < n; j++) {
            if (!done[j] && abs(req[j] - head) < minDiff) {
                minDiff = abs(req[j] - head);
                chosen = j;
            }
        }
        done[chosen] = 1;
        totalMovement += minDiff;
        head = req[chosen];
    }
    printf("Total SSTF Head Movement: %d cylinders\n", totalMovement);
    return 0;
}

